queries:
SELECT AVG(avg_len), AVG(avg_ratio) FROM (SELECT AVG(length) AS avg_len, AVG(rental_rate / replacement_cost) AS avg_ratio FROM film WHERE replacement_cost > 20.99 GROUP BY rating)
SELECT title FROM film WHERE replacement_cost >= 20.99
SELECT AVG(r) FROM (SELECT rating, AVG(rental_rate / replacement_cost) AS r FROM film GROUP BY rating);
SELECT AVG(ratio) AS final_ratio
FROM (
  SELECT rating, AVG(rental_rate) / AVG(replacement_cost) AS ratio
  FROM film
  GROUP BY rating
);
SELECT rating, AVG(length) AS avg_length, AVG(rental_rate * 1.0 / length) AS avg_ratio
FROM film
GROUP BY rating;
SELECT rating, AVG(length) AS avg_length, AVG(rental_rate) AS avg_rental_rate
FROM film
WHERE length IS NOT NULL AND rating IS NOT NULL
GROUP BY rating;
